*{box-sizing:border-box} :root{font-family:'DM Sans',sans-serif;color:#f7f3e8;background:#111713;font-synthesis:none;font-optical-sizing:auto}html,body{margin:0;width:100%;height:100%;overflow:hidden}body{touch-action:none}.game-shell{position:relative;width:100vw;height:100dvh;min-height:540px;overflow:hidden;background:radial-gradient(ellipse at 50% 45%,#344331 0,#202a23 47%,#141b17 100%);isolation:isolate}#scene{position:absolute;inset:0;z-index:0}#scene canvas{display:block;width:100%;height:100%;touch-action:none}.vignette{position:absolute;inset:0;z-index:1;pointer-events:none;background:linear-gradient(180deg,rgba(11,17,14,.62),transparent 25%,transparent 62%,rgba(12,17,14,.5)),radial-gradient(ellipse,transparent 36%,rgba(8,13,11,.25) 100%)}.topbar{position:absolute;z-index:3;top:0;left:0;right:0;height:82px;padding:0 40px;display:flex;align-items:center;gap:14px;border-bottom:1px solid rgba(255,255,255,.075);background:linear-gradient(180deg,rgba(13,19,15,.62),rgba(13,19,15,.1));}.brand{display:flex;align-items:center;gap:10px;font:700 14px 'Space Grotesk',sans-serif;letter-spacing:1.6px;color:#f8f2e5;text-decoration:none}.brand-light{font-weight:500;color:#aab19f}.brand-mark{display:grid;place-items:center;width:34px;height:34px;border:1px solid rgba(243,156,75,.38);border-radius:11px;color:#f7a94c;background:rgba(248,143,49,.09);font-size:19px}.chapter{border-left:1px solid rgba(255,255,255,.14);padding-left:17px;margin-left:10px;display:flex;flex-direction:column;gap:3px}.chapter-kicker,.eyebrow{font-size:9px;font-weight:800;letter-spacing:1.8px;color:#a5ad9e}.chapter-name{font:600 13px 'Space Grotesk',sans-serif}.chapter-name i{font:500 10px 'DM Sans',sans-serif;font-style:normal;color:#919c8c;margin-left:8px}.icon-button{margin-left:auto;border:1px solid rgba(255,255,255,.14);color:#e6eadf;width:34px;height:34px;border-radius:11px;background:rgba(255,255,255,.055);font-size:17px;cursor:pointer}.icon-button+.icon-button{margin-left:-6px}.icon-button:hover{background:rgba(255,255,255,.13)}.mission-card{position:absolute;z-index:2;top:117px;left:40px;width:275px;padding:18px 19px 15px;border:1px solid rgba(228,230,204,.14);border-radius:15px;background:linear-gradient(135deg,rgba(21,29,23,.86),rgba(31,40,31,.7));backdrop-filter:blur(14px);box-shadow:0 14px 40px rgba(0,0,0,.2)}.eyebrow{display:flex;align-items:center;gap:7px}.pulse{width:7px;height:7px;border-radius:99px;background:#d2aa57;box-shadow:0 0 10px #d2aa57}.mission-card h1{font:600 21px 'Space Grotesk',sans-serif;letter-spacing:-.4px;margin:12px 0 4px}.mission-card p{color:#adb5a7;font-size:12px;margin:0 0 17px}.progress-row{display:flex;align-items:center;gap:12px}.progress-track{height:4px;flex:1;background:rgba(255,255,255,.1);border-radius:9px;overflow:hidden}.progress-track span{display:block;height:100%;width:0;background:linear-gradient(90deg,#d37d3c,#ffc665);border-radius:9px;transition:width .5s}.progress-row>b{font:600 12px 'Space Grotesk',sans-serif;color:#f5ca7a;white-space:nowrap}.progress-row small{color:#a1a99a;font-size:10px}.status-pills{position:absolute;z-index:2;top:118px;right:40px;display:flex;gap:8px}.pill{display:flex;align-items:center;gap:8px;padding:9px 12px;border:1px solid rgba(230,233,211,.13);border-radius:10px;background:rgba(19,26,21,.75);backdrop-filter:blur(8px);font-size:9px;letter-spacing:1px;font-weight:800;color:#d4d7c8}.pill-icon{color:#f3ac56;font-size:14px}.pill-icon.heart{color:#d7845e}.hint-toast{position:absolute;z-index:2;top:54%;left:50%;transform:translate(-50%,-50%);padding:10px 15px;border:1px solid rgba(255,255,255,.1);border-radius:30px;background:rgba(17,24,19,.8);color:#e9e7da;font-size:11px;letter-spacing:.25px;opacity:0;transition:opacity .25s;pointer-events:none;white-space:nowrap;backdrop-filter:blur(9px)}.hint-toast.show{opacity:1}.tool-dock{position:absolute;z-index:3;left:50%;bottom:25px;transform:translateX(-50%);width:min(640px,calc(100vw - 48px));padding:15px 17px 11px;background:linear-gradient(150deg,rgba(23,31,25,.94),rgba(17,24,20,.94));border:1px solid rgba(255,255,255,.13);border-radius:17px;box-shadow:0 15px 50px rgba(0,0,0,.34);backdrop-filter:blur(18px)}.dock-top{height:38px;display:flex;justify-content:space-between;align-items:center;padding:0 3px 10px}.dock-top>div:first-child{display:flex;align-items:baseline;gap:9px}.tool-caption{font-size:10px;color:#9da797}.bucket-meter{display:flex;align-items:center;gap:6px;color:#f1aa54}.bucket-icon{font-size:17px}.bucket-label{font-size:9px;letter-spacing:1.2px;font-weight:800}.charge-dots{display:flex;gap:3px;margin-left:3px}.charge-dots i{width:6px;height:6px;border-radius:50%;background:#ef9c48;box-shadow:0 0 7px rgba(239,156,72,.5);transition:all .2s}.charge-dots i.empty{background:#465044;box-shadow:none}.tool-list{display:grid;grid-template-columns:repeat(4,1fr);gap:7px}.tool{position:relative;display:flex;align-items:center;gap:9px;text-align:left;min-width:0;height:54px;padding:0 10px;border:1px solid rgba(255,255,255,.08);border-radius:11px;background:rgba(255,255,255,.035);color:#d8ddcf;cursor:pointer;transition:background .18s,border .18s,transform .18s}.tool:hover{background:rgba(255,255,255,.09);transform:translateY(-1px)}.tool.active{border-color:rgba(234,167,90,.52);background:linear-gradient(120deg,rgba(204,123,54,.22),rgba(193,124,56,.08));box-shadow:inset 0 0 17px rgba(219,133,61,.05)}.tool-glyph{display:grid;place-items:center;width:29px;height:29px;flex:none;border-radius:9px;background:rgba(179,193,166,.1);font-size:19px;color:#c5cfb6}.active .tool-glyph{color:#f0bb72;background:rgba(231,153,80,.15)}.lava-glyph{color:#ff9650}.build-glyph{color:#d9bd87}.break-glyph{color:#c3b9a2}.tool-text{display:flex;flex-direction:column;gap:3px;min-width:0}.tool-text b{font-size:11px;white-space:nowrap}.tool-text small{font-size:9px;color:#9da698;white-space:nowrap}.tool kbd{position:absolute;right:7px;top:6px;padding:1px 4px;border:1px solid rgba(255,255,255,.1);border-radius:4px;color:#879183;font:9px 'DM Sans',sans-serif}.dock-foot{display:flex;align-items:center;gap:7px;height:27px;padding:7px 3px 0;color:#9ba497;font-size:9px}.tip-dot{display:grid;place-items:center;width:12px;height:12px;border:1px solid #87937c;border-radius:50%;font-size:8px}.touch-hint{margin-left:auto;font-size:8px;letter-spacing:1px;color:#758071}.touch-hint b{color:#bd8657;padding:0 4px}.corner-label{position:absolute;z-index:2;bottom:37px;right:40px;font-size:8px;letter-spacing:1.6px;color:rgba(231,234,217,.42)}.mobile-actions{display:none}.modal{position:absolute;z-index:10;inset:0;display:grid;place-items:center;background:rgba(10,15,12,.64);backdrop-filter:blur(8px);padding:18px}.modal.hidden,.win-banner.hidden{display:none}.modal-card{position:relative;width:min(440px,100%);padding:32px;border:1px solid rgba(255,255,255,.15);border-radius:20px;background:linear-gradient(145deg,#27332a,#18221b);box-shadow:0 24px 80px rgba(0,0,0,.5)}.modal-close{position:absolute;right:15px;top:11px;border:0;background:none;color:#b6c0b0;font-size:26px;cursor:pointer}.modal-icon{display:block;color:#f2a74e;font-size:30px;margin-bottom:12px}.modal-card h2{font:600 24px 'Space Grotesk',sans-serif;margin:12px 0}.modal-card p{font-size:13px;line-height:1.65;color:#b9c1b2}.modal-card p b{color:#f0d7a4}.modal-controls{display:flex;justify-content:space-between;margin:20px 0;color:#909b8c;font-size:8px;letter-spacing:1px}.modal-controls b{display:block;color:#d6ddce;font-size:9px;margin-top:5px}.primary-button{display:flex;justify-content:space-between;align-items:center;width:100%;padding:13px 15px;border:0;border-radius:10px;background:#d78748;color:#1b1b15;font-size:10px;font-weight:800;letter-spacing:1.4px;cursor:pointer}.primary-button span{font-size:17px}.win-banner{position:absolute;z-index:5;left:50%;top:50%;transform:translate(-50%,-50%);width:min(500px,calc(100% - 32px));display:flex;align-items:center;gap:13px;padding:17px;border:1px solid rgba(236,188,112,.38);border-radius:15px;background:rgba(26,35,27,.95);box-shadow:0 12px 50px #0007}.win-spark{font-size:27px;color:#f0ae57}.win-banner b,.win-banner span{display:block}.win-banner b{font:600 15px 'Space Grotesk',sans-serif}.win-banner span{font-size:10px;color:#adb6a6;margin-top:4px}.win-banner button{margin-left:auto;white-space:nowrap;border:1px solid #64735c;border-radius:7px;padding:8px;color:#dfe3d2;background:transparent;font-size:8px;font-weight:800;letter-spacing:.8px;cursor:pointer}
@media(max-width:700px){.game-shell{min-height:0}.topbar{height:62px;padding:0 16px}.brand{font-size:11px;gap:7px;letter-spacing:1px}.brand-mark{width:29px;height:29px;border-radius:9px;font-size:16px}.chapter{padding-left:10px;margin-left:2px}.chapter-kicker{font-size:7px;letter-spacing:1.3px}.chapter-name{font-size:11px}.chapter-name i{font-size:8px;margin-left:3px}.icon-button{width:30px;height:30px;border-radius:9px;font-size:14px}.mission-card{top:77px;left:14px;width:205px;padding:12px 13px 11px;border-radius:12px}.eyebrow{font-size:8px;letter-spacing:1.4px}.mission-card h1{font-size:16px;margin:9px 0 3px}.mission-card p{font-size:10px;margin-bottom:11px}.progress-row{gap:7px}.progress-row>b{font-size:10px}.progress-track{height:3px}.status-pills{top:78px;right:14px;gap:5px;flex-direction:column;align-items:flex-end}.pill{gap:6px;padding:7px 9px;border-radius:9px;font-size:8px}.pill-icon{font-size:12px}.tool-dock{width:calc(100vw - 20px);bottom:max(9px,env(safe-area-inset-bottom));padding:10px 10px 6px;border-radius:14px}.dock-top{height:30px;padding:0 2px 6px}.dock-top>div:first-child{gap:6px}.tool-caption{font-size:9px}.bucket-meter{gap:4px}.bucket-label{font-size:8px}.bucket-icon{font-size:15px}.charge-dots{gap:2px}.charge-dots i{width:5px;height:5px}.tool-list{gap:5px}.tool{height:48px;gap:5px;padding:0 6px;border-radius:9px}.tool-glyph{width:24px;height:24px;border-radius:7px;font-size:16px}.tool-text{gap:2px}.tool-text b{font-size:9px}.tool-text small{font-size:7px}.tool kbd{display:none}.dock-foot{height:21px;padding-top:5px;font-size:8px}.touch-hint{font-size:7px;letter-spacing:.5px}.corner-label{display:none}.hint-toast{top:54%;font-size:10px}.mobile-actions{position:absolute;z-index:2;display:flex;gap:7px;right:15px;bottom:151px}.mobile-actions button{width:35px;height:35px;border:1px solid rgba(255,255,255,.17);border-radius:10px;background:rgba(19,26,21,.7);color:#e6ddca;font-size:20px;backdrop-filter:blur(8px)}.modal-card{padding:25px 22px}.modal-card h2{font-size:21px}.modal-card p{font-size:12px}.win-banner{flex-wrap:wrap}.win-banner button{margin-left:40px}.vignette{background:linear-gradient(180deg,rgba(11,17,14,.46),transparent 27%,transparent 62%,rgba(12,17,14,.43))}}
@media(max-width:390px){.chapter{display:none}.mission-card{width:185px}.tool{gap:4px;padding:0 4px}.tool-glyph{width:21px;height:21px}.tool-text b{font-size:8px}.tool-text small{font-size:6px}.touch-hint{letter-spacing:0}}

import * as THREE from 'https://cdn.jsdelivr.net/npm/three@0.169.0/build/three.module.js';

const host=document.querySelector('#scene');
const scene=new THREE.Scene(); scene.background=new THREE.Color('#202a21'); scene.fog=new THREE.Fog('#202a21',18,34);
const renderer=new THREE.WebGLRenderer({antialias:true,alpha:false}); renderer.setPixelRatio(Math.min(devicePixelRatio,2)); renderer.shadowMap.enabled=true; renderer.shadowMap.type=THREE.PCFSoftShadowMap; renderer.outputColorSpace=THREE.SRGBColorSpace; renderer.toneMapping=THREE.ACESFilmicToneMapping; renderer.toneMappingExposure=1.15; host.appendChild(renderer.domElement);
const camera=new THREE.OrthographicCamera(-7,7,7,-7,.1,100); let cameraZoom=1,cameraAngle=0;
const target=new THREE.Vector3(5,0,5);
function placeCamera(){const h=Math.max(12.8,15.2/(innerWidth/innerHeight))/cameraZoom;const w=h*innerWidth/innerHeight;camera.left=-w/2;camera.right=w/2;camera.top=h/2;camera.bottom=-h/2;const a=cameraAngle;camera.position.set(target.x+Math.sin(a+Math.PI/4)*17,19,target.z+Math.cos(a+Math.PI/4)*17);camera.lookAt(target);camera.updateProjectionMatrix();}
placeCamera();
scene.add(new THREE.HemisphereLight('#d5dfc0','#384333',2.0));
const sun=new THREE.DirectionalLight('#ffdfaa',3.3);sun.position.set(-7,16,9);sun.castShadow=true;sun.shadow.mapSize.set(2048,2048);sun.shadow.camera.left=-13;sun.shadow.camera.right=13;sun.shadow.camera.top=13;sun.shadow.camera.bottom=-13;sun.shadow.bias=-.0003;scene.add(sun);
const fill=new THREE.DirectionalLight('#9fc7bf',.75);fill.position.set(12,9,-9);scene.add(fill);
const mat=(color,roughness=.88,extra={})=>new THREE.MeshStandardMaterial({color,roughness,...extra});
const mats={soil:mat('#394a38'),tileA:mat('#536446'),tileB:mat('#4b5e40'),edge:mat('#857659'),wood:mat('#805331'),woodLight:mat('#aa7442'),stone:mat('#737769'),stoneLight:mat('#93937d'),leaf:mat('#536b46'),darkLeaf:mat('#384f39'),grass:mat('#9ca76b'),gold:mat('#f3c46b',.4,{emissive:'#d47c27',emissiveIntensity:.28})};
const floorGroup=new THREE.Group(),objectGroup=new THREE.Group(),effectGroup=new THREE.Group(),decorGroup=new THREE.Group();scene.add(floorGroup,decorGroup,objectGroup,effectGroup);
const tileMeshes=new Map(),objects=new Map(),lava=new Map(),pickups=new Map();const key=(x,z)=>`${x},${z}`,inside=(x,z)=>x>=0&&x<11&&z>=0&&z<11;
const boxGeo=new THREE.BoxGeometry(1,1,1);
function box(parent,geo,material,x,y,z,sx=1,sy=1,sz=1){const m=new THREE.Mesh(geo,material);m.position.set(x,y,z);m.scale.set(sx,sy,sz);m.castShadow=true;m.receiveShadow=true;parent.add(m);return m;}
// Floating garden plinth and the quiet, mossy grid beneath it.
box(floorGroup,boxGeo,mat('#353f31'),5,-.4,5,12,.75,12);
box(floorGroup,boxGeo,mat('#756c52'),5,-.79,5,12.25,.12,12.25);
for(let z=0;z<11;z++)for(let x=0;x<11;x++){
 const tile=box(floorGroup,boxGeo,mat((x+z)%2?'#506044':'#596849'),x,0,z,.98,.12,.98);tile.position.y=-.065;tile.userData={x,z};tileMeshes.set(key(x,z),tile);
 if((x*13+z*7)%9===0){const tuft=box(decorGroup,new THREE.ConeGeometry(.045,.17,4),mats.grass,x-.22,-.005,z+.18,.65,1,.65);tuft.rotation.z=.14;}
}
// Worn paving stones mark the path through the overgrown courtyard.
for(let i=1;i<10;i++){for(const [x,z] of [[i,1],[9,i]]){const p=box(decorGroup,boxGeo,mat('#777760'),x,.015,z,.78,.08,.78);p.rotation.y=((i*3)%5)*.12;}}
function makeObject(x,z,type){
 const g=new THREE.Group();g.position.set(x,0,z);objectGroup.add(g);let solid=true;
 if(type==='wood'){
  const body=box(g,boxGeo,mats.wood,0,.39,0,.78,.72,.72);body.userData.burnable=true;
  for(const s of [-1,1]){box(g,boxGeo,mats.woodLight,s*.31,.44,0,.12,.9,.82);}
  box(g,boxGeo,mats.woodLight,0,.52,0,.79,.14,.83);
  box(g,boxGeo,mats.wood,-.04,.24,0,.78,.14,.77);
  g.userData={x,z,type,health:0};
 }else if(type==='stone'){
  const b=box(g,new THREE.DodecahedronGeometry(.48,0),mats.stone,0,.39,0,.92,.84,.9);b.rotation.set(.16,.3,.1);
  const chip=box(g,new THREE.DodecahedronGeometry(.16,0),mats.stoneLight,.22,.71,-.1,.9,.7,.8);chip.rotation.y=.4;
  g.userData={x,z,type};
 }else if(type==='shrub'){
  for(let i=0;i<5;i++){const a=i*1.26;const b=box(g,new THREE.DodecahedronGeometry(.29,1),i%2?mats.leaf:mats.darkLeaf,Math.cos(a)*.18,.27+(i%2)*.12,Math.sin(a)*.18,1.1,1,.9);b.rotation.set(a,.2,a*.2);}
  g.userData={x,z,type};
 }
 objects.set(key(x,z),g);return g;
}
// A deliberate, legible route: vines and gates block the shortcut, but every ember is reachable.
[[3,1],[4,2],[4,3],[7,4],[7,5],[5,7],[6,8],[2,7]].forEach(([x,z])=>makeObject(x,z,'wood'));
[[6,2],[6,3],[8,6],[3,8]].forEach(([x,z])=>makeObject(x,z,'stone'));
[[2,4],[8,2],[3,6],[9,8],[5,4],[1,8],[8,9],[4,9]].forEach(([x,z])=>makeObject(x,z,'shrub'));
// Mossy perimeter boulders and a few sculpted, low-poly trees.
function tree(x,z,size=1){const g=new THREE.Group();g.position.set(x,0,z);decorGroup.add(g);box(g,new THREE.CylinderGeometry(.09,.16,.9,6),mat('#67513a'),0,.42,0,size,size,size);for(let i=0;i<3;i++){const crown=new THREE.Mesh(new THREE.IcosahedronGeometry(.54-i*.09,1),i===1?mats.leaf:mats.darkLeaf);crown.position.set((i%2-.5)*.2,.92+i*.26,0);crown.scale.set(size,size*.85,size);crown.castShadow=true;g.add(crown);}}
[[.1,.3,1.2],[10.8,.4,.9],[.3,10.6,1],[10.8,10.5,1.15],[1.3,10.9,.8],[9.6,.1,.8]].forEach(v=>tree(...v));
for(let i=0;i<21;i++){let x=(i*17%109)/10,z=(i*31%109)/10;if((x<1||x>10||z<1||z>10)&&inside(Math.floor(x),Math.floor(z)))box(decorGroup,new THREE.DodecahedronGeometry(.22+(i%3)*.06),i%2?mats.stone:mats.darkLeaf,x,.03,z,1,1.25,.9);}
// Ember seed pedestals.
function addEmber(x,z){const g=new THREE.Group();g.position.set(x,0,z);decorGroup.add(g);const base=new THREE.Mesh(new THREE.CylinderGeometry(.28,.34,.18,7),mat('#776347'));base.position.y=.08;base.castShadow=true;g.add(base);const orb=new THREE.Mesh(new THREE.OctahedronGeometry(.22,1),mats.gold);orb.position.y=.46;orb.castShadow=true;g.add(orb);const light=new THREE.PointLight('#ff9c42',1.1,2.4);light.position.y=.6;g.add(light);pickups.set(key(x,z),{group:g,orb,light,got:false,x,z});}
[[9,2],[8,8],[2,9]].forEach(([x,z])=>addEmber(x,z));
// Player figure: an ember-orange explorer with a tiny carried bucket.
const player=new THREE.Group();scene.add(player);const playerBody=new THREE.Mesh(new THREE.CapsuleGeometry(.22,.38,4,8),mat('#d58b54',.65));playerBody.position.y=.52;playerBody.castShadow=true;player.add(playerBody);const hood=new THREE.Mesh(new THREE.SphereGeometry(.24,10,8),mat('#b96842'));hood.position.set(0,.82,0);hood.castShadow=true;player.add(hood);const pack=box(player,boxGeo,mat('#66543b'),0,.48,-.22,.25,.3,.13);const bucket=new THREE.Mesh(new THREE.CylinderGeometry(.12,.16,.22,8,1,true),mat('#c5a872',.5,{metalness:.2}));bucket.position.set(.28,.28,.05);bucket.rotation.z=-.12;bucket.castShadow=true;player.add(bucket);
const state={x:1,z:1,tool:'move',planks:5,charges:3,collected:0,burning:0,walkQueue:[],walking:false,sound:true,won:false};player.position.set(state.x,0,state.z);

const $=s=>document.querySelector(s),toastEl=$('#toast');let toastTimer;
function toast(text){toastEl.textContent=text;toastEl.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>toastEl.classList.remove('show'),2100);}
const captions={move:['Choose a tile to move','Tap a nearby tile to walk there.'],pour:['Pour a little lava','Burn timber or warm the ground.'],build:['Rebuild the courtyard','Place a plank wall on clear ground.'],break:['Clear the way','Dismantle an obstacle and reclaim planks.']};
function setTool(t){state.tool=t;document.querySelectorAll('.tool').forEach(b=>b.classList.toggle('active',b.dataset.tool===t));$('#toolCaption').textContent=captions[t][0];$('#toolTip').textContent=captions[t][1];}
document.querySelectorAll('.tool').forEach(b=>b.addEventListener('click',()=>setTool(b.dataset.tool)));
function hud(){const dots=$('#chargeDots').children;[...dots].forEach((d,i)=>d.classList.toggle('empty',i>=state.charges));$('#scrapCount').textContent=state.planks;$('#progressCount').innerHTML=`${state.collected} <small>/ 3</small>`;$('#progressFill').style.width=`${state.collected/3*100}%`;const close=[...lava.values()].some(l=>Math.abs(l.x-state.x)+Math.abs(l.z-state.z)<=2);$('#heatStatus').textContent=close?'HEAT NEARBY':'COOL ENOUGH';$('#heatStatus').style.color=close?'#f0a267':'';}
function distance(x,z){return Math.abs(state.x-x)+Math.abs(state.z-z)}
function getPath(sx,sz,tx,tz){const q=[[sx,sz]],prev=new Map([[key(sx,sz),null]]);while(q.length){const [x,z]=q.shift();if(x===tx&&z===tz)break;for(const [nx,nz] of [[x+1,z],[x-1,z],[x,z+1],[x,z-1]]){const k=key(nx,nz);if(!inside(nx,nz)||prev.has(k)||objects.has(k)||lava.has(k))continue;prev.set(k,key(x,z));q.push([nx,nz]);}}const end=key(tx,tz);if(!prev.has(end))return null;const path=[];let k=end;while(k&&k!==key(sx,sz)){const [x,z]=k.split(',').map(Number);path.unshift([x,z]);k=prev.get(k);}return path;}
function collectHere(){const p=pickups.get(key(state.x,state.z));if(p&&!p.got){p.got=true;state.collected++;p.group.visible=false;hud();toast(`Ember seed found · ${state.collected} of 3`);if(state.collected===3){state.won=true;$('#missionTitle').textContent='The courtyard is yours';$('#missionCopy').textContent='All three ember seeds are back home.';$('#winBanner').classList.remove('hidden');}}}
